        }
        String placeholders = String.join(",", java.util.Collections.nCopies(sourceKeys.size(), "?"));
        return jdbc.query(
                SOURCE_SELECT + " FROM water_source WHERE source_key IN (" + placeholders
                        + ") ORDER BY source_key ASC FOR UPDATE",
