package com.example.starter.water.dto;

import java.util.List;

/**
 * 灌区配水 API 请求/响应契约。水量在 API 层一律使用十进制字符串（单位立方米，最多 3 位小数），
 * 时间使用 ISO-8601 UTC 字符串。
 */
public final class Dtos {

    private Dtos() {
    }

    /** 创建供水窗口命令。 */
    public record CreateWindowRequest(String commandKey, String windowKey, String channelId,
                                      String startUtc, String endUtc, String plannedVolume) {
    }

    /** 供水窗口视图；activeCurtailmentVolume 为 null 表示无生效限供。 */
    public record WindowResponse(long id, String windowKey, String channelId, String startUtc, String endUtc,
                                 String plannedVolume, String activeCurtailmentVolume, String availableTotal,
                                 String createdUtc) {
    }

    /** 提交配水申请命令；申请人由 X-Actor-Id 请求头提供；salinityLimit 可选，单位 mg/L。 */
    public record SubmitAllocationRequest(String commandKey, String allocationKey, Long windowId,
                                          String userId, String amount, String salinityLimit) {
    }

    /**
     * 配水申请视图。状态：REQUESTED / APPROVED / CANCELLED。
     * amount 为不可改写的原申请水量；heldAmount 为当前持有额度（REQUESTED 为 0，普通批准时等于原水量，
     * 转出或掺配核销时等额扣减，取消时归零；持有额度恰为零的已转出/已核销申请仍为 APPROVED）。
     * salinityLimit 为申请声明的盐度上限（mg/L），null 表示不限制；version 为乐观版本，每次扣减自增。
     */
    public record AllocationResponse(String allocationKey, long windowId, String userId, String amount,
                                     String heldAmount, String salinityLimit, long version,
                                     String requester, String status,
                                     String createdUtc, String updatedUtc) {
    }

    /** 仅含幂等键的命令（批准/取消申请、取消限供）。 */
    public record CommandRequest(String commandKey) {
    }

    /** 创建限供命令。 */
    public record CurtailmentRequest(String commandKey, String volume) {
    }

    /** 限供视图。状态：ACTIVE / CANCELLED；cancelledUtc 未取消时为 null。 */
    public record CurtailmentResponse(long id, long windowId, String volume, String status,
                                      String createdUtc, String cancelledUtc) {
    }

    /** 窗口当前可用容量视图；approvedTotal 汇总 APPROVED 申请的当前持有额度。 */
    public record CapacityResponse(long windowId, String plannedVolume, String activeCurtailmentVolume,
                                   String availableTotal, String approvedTotal, String remaining) {
    }

    /** 同窗口额度转让命令；操作人（源申请人）由 X-Actor-Id 请求头提供。 */
    public record TransferRequest(String commandKey, String transferKey, String sourceAllocationKey,
                                  String targetAllocationKey) {
    }

    /** 转让流水视图，创建后不可变，不提供撤销。 */
    public record TransferResponse(String transferKey, long windowId, String sourceAllocationKey,
                                   String targetAllocationKey, String amount, String actor, String createdUtc) {
    }

    /** 窗口转让流水列表视图。 */
    public record TransferListResponse(long windowId, List<TransferResponse> transfers) {
    }

    /** 窗口历史明细：窗口本身 + 全部申请 + 全部限供记录。 */
    public record HistoryResponse(WindowResponse window, List<AllocationResponse> allocations,
                                  List<CurtailmentResponse> curtailments) {
    }

    // ------------------------------------------------------------------
    // 水源水质掺配
    // ------------------------------------------------------------------

    /** 注册水源命令；availableAmount 单位立方米（最多 3 位小数），salinity 单位 mg/L（非负）。 */
    public record CreateSourceRequest(String commandKey, String sourceKey, String availableAmount,
                                      String salinity) {
    }

    /**
     * 修改水源盐度命令；必须携带 expectedVersion 做乐观裁决，版本不符返回 409。
     * 修改只影响后续核销，不改写历史掺配快照。
     */
    public record UpdateSourceSalinityRequest(String commandKey, Long expectedVersion, String salinity) {
    }

    /** 水源视图；availableAmount 为当前可用余量，version 为当前乐观版本（创建为 0）。 */
    public record SourceResponse(long id, String sourceKey, String availableAmount, String salinity,
                                 long version, String createdUtc, String updatedUtc) {
    }

    /** 掺配核销中的一项水源取水；amount 单位立方米，最多 3 位小数，必须为正。 */
    public record BlendItemRequest(String sourceKey, String amount) {
    }

    /**
     * 水质掺配核销命令：对申请做一次核销，选取 1 至 5 个水源及各自取水量。
     * 水源集合换序视为同参；writeOffAmount 为本次核销量（从申请剩余额度扣减）。
     */
    public record BlendWriteOffRequest(String commandKey, String blendKey, String allocationKey,
                                       String writeOffAmount, List<BlendItemRequest> items) {
    }

    /** 掺配快照明细视图，冻结核销时水源盐度。 */
    public record BlendItemResponse(String sourceKey, String amount, String salinity, int ordinal) {
    }

    /** 掺配核销快照视图，创建后不可变；weightedSalinity 为加权平均盐度计算值（mg/L）。 */
    public record BlendSnapshotResponse(String blendKey, String allocationKey, String actor,
                                        String totalAmount, String weightedSalinity, String salinityLimit,
                                        long allocationVersion, String createdUtc,
                                        List<BlendItemResponse> items) {
    }

    /** 申请掺配快照列表视图。 */
    public record BlendSnapshotListResponse(String allocationKey, List<BlendSnapshotResponse> snapshots) {
    }

    /**
     * 申请累计水质视图：totalWrittenOff 为累计核销量，remainingHeld 为申请剩余额度，
     * cumulativeWeightedSalinity 为全部核销按核销量加权的累计平均盐度（mg/L），无核销时为 null。
     */
    public record AllocationBlendSummaryResponse(String allocationKey, String status, String amount,
                                                 String heldAmount, String totalWrittenOff,
                                                 String remainingHeld, String salinityLimit,
                                                 String cumulativeWeightedSalinity,
                                                 List<BlendSnapshotResponse> snapshots) {
    }

    /** 统一错误响应体。 */
    public record ErrorResponse(String code, String message) {
    }
}

input.old_string:
/**
 * 水质掺配核销：在同一事务内校验并扣减全部水源可用量与申请剩余额度，写入不可变快照。
 * 任一水源余量不足、取水量合计不等于核销量或加权平均盐度高于申请上限均 422 整单回滚；
 * 任一扣减失败整单回滚。水源集合按 source_key 升序规范化，换序视为同参。
 */
public BlendSnapshotResponse blendWriteOff(String commandKey, String blendKey, String allocationKey,
                                           String writeOffAmount, List<BlendItemRequest> items,
                                           String actor) {
    requireKey("commandKey", commandKey);
    requireKey("blendKey", blendKey);
    requireKey("allocationKey", allocationKey);
    requireKey("X-Actor-Id", actor);
    BigDecimal total = parseAmount("writeOffAmount", writeOffAmount);
    if (items == null || items.size() < BLEND_MIN_SOURCES || items.size() > BLEND_MAX_SOURCES) {
        throw ApiException.badRequest("INVALID_ARGUMENT",
                "items 必须包含 " + BLEND_MIN_SOURCES + " 至 " + BLEND_MAX_SOURCES + " 个水源");
    }
    // 规范化：按 source_key 升序；同一核销内水源不得重复
    TreeMap<String, BigDecimal> normalized = new TreeMap<>();
    for (BlendItemRequest item : items) {
        if (item == null) {
            throw ApiException.badRequest("INVALID_ARGUMENT", "items 不能包含空元素");
        }
        requireKey("items.sourceKey", item.sourceKey());
        BigDecimal qty = parseAmount("items.amount", item.amount());
        if (normalized.put(item.sourceKey(), qty) != null) {
            throw ApiException.badRequest("DUPLICATE_SOURCE",
                    "同一核销内水源不得重复: " + item.sourceKey());
        }
    }
    String params = blendParams(actor, allocationKey, total, normalized);
    return runCommand("BLEND_WRITE_OFF", commandKey, params, BlendSnapshotResponse.class, () -> {
        if (repository.findBlendSnapshotByKey(blendKey) != null) {
            throw ApiException.conflict("BLEND_KEY_REUSED", "blendKey 已被使用: " + blendKey);
        }
        AllocationRow allocation = repository.lockAllocationByKey(allocationKey);
        if (allocation == null) {
            throw ApiException.notFound("ALLOCATION_NOT_FOUND", "配水申请不存在: " + allocationKey);
        }
        if (STATUS_CANCELLED.equals(allocation.status())) {
            throw ApiException.conflict("ALLOCATION_CANCELLED", "已取消的申请不能核销");
        }
        if (!STATUS_APPROVED.equals(allocation.status())) {
            throw ApiException.conflict("ALLOCATION_NOT_APPROVED", "只有 APPROVED 的申请可以核销");
        }
        if (allocation.heldAmount().compareTo(total) < 0) {
            throw ApiException.unprocessable("INSUFFICIENT_ALLOCATION_HELD",
                    "申请剩余额度 " + fmt(allocation.heldAmount()) + " 不足，无法核销 " + fmt(total));
        }
        // 按规范化顺序一次性锁定水源行，与盐度修改、其它核销按事务提交顺序串行裁决
        List<String> sourceKeys = List.copyOf(normalized.keySet());
        List<SourceRow> locked = repository.lockSourcesByKeys(sourceKeys);
        if (locked.size() != sourceKeys.size()) {
            List<String> found = locked.stream().map(SourceRow::sourceKey).sorted().toList();
            List<String> missing = new ArrayList<>(sourceKeys);
            missing.removeAll(found);
            throw ApiException.notFound("SOURCE_NOT_FOUND", "水源不存在: " + missing);
        }
        Map<String, SourceRow> rows = new LinkedHashMap<>();
        for (SourceRow row : locked) {
            rows.put(row.sourceKey(), row);
        }
        // 1) 各水源可用量必须充足
        for (Map.Entry<String, BigDecimal> entry : normalized.entrySet()) {
            SourceRow source = rows.get(entry.getKey());
            if (source.availableAmount().compareTo(entry.getValue()) < 0) {
                throw ApiException.unprocessable("SOURCE_INSUFFICIENT",
                        "水源 " + entry.getKey() + " 余量 " + fmt(source.availableAmount())
                                + " 不足，本次拟取 " + fmt(entry.getValue()));
            }
        }
        // 2) 取水量合计必须等于申请核销量（总量守恒）
        BigDecimal itemSum = normalized.values().stream().reduce(BigDecimal.ZERO, BigDecimal::add);
        if (itemSum.compareTo(total) != 0) {
            throw ApiException.unprocessable("BLEND_TOTAL_MISMATCH",
                    "各水源取水量合计 " + fmt(itemSum) + " 不等于申请核销量 " + fmt(total));
        }
        // 3) 加权平均盐度不得高于申请上限
        BigDecimal weighted = weightedSalinity(normalized, rows, total);
        if (allocation.salinityLimit() != null
                && weighted.compareTo(allocation.salinityLimit()) > 0) {
            throw ApiException.unprocessable("SALINITY_EXCEEDED",
                    "加权平均盐度 " + fmt(weighted) + " mg/L 高于申请上限 "
                            + fmt(allocation.salinityLimit()) + " mg/L");
        }
        // 全部校验通过：跨表原子扣减 + 不可变快照，任一失败由事务整单回滚
        long now = nowNanos();
        long allocationVersionBefore = allocation.version();
        for (Map.Entry<String, BigDecimal> entry : normalized.entrySet()) {
            repository.decrementSourceAmount(rows.get(entry.getKey()).id(), entry.getValue());
        }
        repository.decrementHeldAmount(allocation.id(), total, now);
        long snapshotId = repository.insertBlendSnapshot(blendKey, allocationKey, actor, total,
                weighted, allocation.salinityLimit(), allocationVersionBefore, now);
        int ordinal = 0;
        for (Map.Entry<String, BigDecimal> entry : normalized.entrySet()) {
            repository.insertBlendItem(snapshotId, entry.getKey(), entry.getValue(),
                    rows.get(entry.getKey()).salinity(), ordinal++);
        }
        return toBlendSnapshotResponse(repository.findBlendSnapshotByKey(blendKey));
    });
}

